using Godot;
using System;
using System.Linq;
using HakutaiKagami.Core.Contracts;
public partial class NewGameRuntime
{
    static string TreatyClauses(TreatyClause clauses)=>string.Join("・",new[]{(TreatyClause.NonAggression,"不侵略"),(TreatyClause.Passage,"通行"),(TreatyClause.Supply,"補給協議"),(TreatyClause.Defense,"防衛援軍協議")}.Where(p=>(clauses&p.Item1)!=0).Select(p=>p.Item2));
    void ShowTreatyNegotiation()
    {
        var w=Snapshot();if(OwnPoliticalHouse(w) is not {} own||!TreatyNegotiations.Enabled(w))return;long shown=Session.Revision;var popup=new PopupPanel();AddChild(popup);var panel=new PanelContainer();panel.AddThemeStyleboxOverride("panel",WorkBox("1d2b34","b7a16a",14));popup.AddChild(panel);var scroll=new ScrollContainer{CustomMinimumSize=new(560,440),HorizontalScrollMode=ScrollContainer.ScrollMode.Disabled};panel.AddChild(scroll);var box=new VBoxContainer{CustomMinimumSize=new(530,0)};scroll.AddChild(box);
        void Text(string text)=>box.AddChild(new Label{Text=text,AutowrapMode=TextServer.AutowrapMode.WordSmart});
        void Button(string text,Action action,bool disabled=false){var b=new Button{Text=text,Disabled=disabled};box.AddChild(b);b.Pressed+=action;}
        void Run(TreatyOperationInput i){Submit(Session.OperateTreaty(i,Session.PlayerControl,shown));popup.Hide();Refresh();}
        Text("正式条約・独立条項");Text("同じ版の承諾が届いて成立します。相手は本人が知る代表者・本拠へ発送し、未通知の交代先は追尾しません。援軍・補給は要請と受領の段階までで、実出陣・物資供与・通行軍対応は後続です。");
        var targets=w.Definitions.Organizations.Where(o=>o.Id!=own).OrderBy(o=>o.Name,StringComparer.Ordinal).ToArray();var target=new OptionButton();foreach(var t in targets)target.AddItem(t.Name);box.AddChild(target);
        var options=new[]{(TreatyClause.NonAggression,"互いに新たな戦を仕掛けない"),(TreatyClause.Passage,"通行の約束"),(TreatyClause.Supply,"補給を協議する条項"),(TreatyClause.Defense,"防衛援軍を協議する条項")}.Select(t=>(t.Item1,Box:new CheckBox{Text=t.Item2,ButtonPressed=t.Item1==TreatyClause.NonAggression})).ToArray();foreach(var item in options)box.AddChild(item.Box);
        var days=new SpinBox{MinValue=1,MaxValue=90,Value=30,Step=1,Suffix="日間"};box.AddChild(days);var notice=new SpinBox{MinValue=1,MaxValue=7,Value=1,Step=1,Suffix="日前に解除予告"};box.AddChild(notice);
        Button("この版の条件を発送",()=>{if(targets.Length==0)return;var clauses=options.Where(x=>x.Box.ButtonPressed).Aggregate(TreatyClause.None,(a,x)=>a|x.Item1);Submit(Session.NegotiateTreaty(new(new("request:treaty-ui/"+shown),TreatyAction.Propose,own,targets[target.Selected].Id,Days:(int)days.Value,Clauses:clauses,NoticeDays:(int)notice.Value),Session.PlayerControl,shown));popup.Hide();Refresh();});
        foreach(var f in TreatyNegotiations.Known(w,Session.PlayerControl)){var other=f.Terms.A==own?f.Terms.B:f.Terms.A;Text("確認した条約 第"+f.Terms.Version+"版 ／ "+TreatyClauses(f.Terms.Clauses)+" ／ 期限 "+f.Terms.Until+"秒");
            var end=new TreatyOperationInput(new("request:treaty-end-ui/"+shown+"/"+f.Acceptance.Value),TreatyOperation.Terminate,f.Acceptance,own,other,EffectiveAt:Session.Seconds+f.Terms.NoticeSeconds);Button("通知期間を守って解除を予告",()=>Run(end),!TreatyNegotiations.CanOperate(w,end,Session.PlayerControl));
            foreach(var kind in new[]{TreatyOperation.RequestDefense,TreatyOperation.RequestSupply}){var i=new TreatyOperationInput(new("request:treaty-request-ui/"+shown+"/"+kind+"/"+f.Acceptance.Value),kind,f.Acceptance,own,other,ReplyBy:Math.Min(f.Terms.Until,Session.Seconds+3*86400),Amount:20,Evidence:kind==TreatyOperation.RequestDefense?"防衛の援軍について協議したい":"補給米20について協議したい");Button(kind==TreatyOperation.RequestDefense?"防衛援軍の相談を発送（受領確認まで）":"補給20の相談を発送（受領確認まで）",()=>Run(i),!TreatyNegotiations.CanOperate(w,i,Session.PlayerControl));}}
        foreach(var card in TreatyNegotiations.OperationView(w).TakeLast(4)){Text(card.Status);if(card.CanResend){var p=w.Treaties!.Operations.Single(p=>p.Input.Id==card.Id);var i=new TreatyOperationInput(new("request:treaty-retry-ui/"+shown+"/"+card.Id.Value),TreatyOperation.Resend,p.Input.Acceptance,p.Input.Owner,p.Input.Target,p.Input.Id);Button("本人が不達を知った同じ原本を再送",()=>Run(i));}}
        Button("地図へ戻る",()=>popup.Hide());popup.PopupHide+=()=>popup.QueueFree();popup.PopupCentered(new Vector2I(600,500));
    }
    void ShowTreatyLetter(EntityId id)
    {
        var known=Branch(Session.PlayerControl).Knowledge.Messages.Single(m=>m.Id==id);if(known.KnownBody==null)return;var w=Snapshot();long shown=Session.Revision;
        if(w.Treaties!.Operations.SingleOrDefault(p=>p.Message==id.Value) is {} op){string line=op.Kind switch{TreatyOperation.Terminate=>"条約に定めた予告期間を置き、この原本の解除を通知する。発送だけで即時解除にはならない。",TreatyOperation.TerminationReceipt=>"解除通知を受領した。法的な受領資格と通知時点を記録して返す。",TreatyOperation.RequestDefense=>"防衛援軍について協議したい。受領返書と実際の出陣・到着は別に確認する。",TreatyOperation.RequestSupply=>"補給について協議したい。受領返書だけで米が届いたことにはしない。",TreatyOperation.Decline=>"この要請は辞退する。",_=>"要請を受領した。援軍・補給の実行が終わったという返答ではない。"};PresentWork("条約の通知・要請",line,TreatyClauses(op.Terms.Clauses)+(op.ObservedAt is {} observed?" ／ 観測 "+observed+"秒":"")+" ／ 元の条約期限 "+op.Terms.Until+"秒",op.Author,op.Author,"本人開封した差出人","確認した書状");var kind=op.Kind==TreatyOperation.Terminate?TreatyOperation.TerminationReceipt:TreatyOperation.Acknowledge;foreach(var action in new[]{kind,TreatyOperation.Decline}){var i=new TreatyOperationInput(new("request:treaty-letter-response/"+shown+"/"+action),action,op.Input.Acceptance,op.Input.Target,op.Input.Owner,op.Input.Id);if(TreatyNegotiations.CanOperate(w,i,Session.PlayerControl))Choice("treaty-"+action,action==TreatyOperation.Decline?"要請を辞退する":"受領したことを返書する",()=>{Submit(Session.OperateTreaty(i,Session.PlayerControl,shown));CloseBottomTalk();});}}
        else{var p=w.Treaties.Papers.Single(p=>p.Message==id.Value);var card=Session.TreatyView().SingleOrDefault(c=>c.Paper==p.Input.Id);string line=p.Input.Action switch{TreatyAction.Counter=>"同じ独立条項を保ち、30日以内の条件を対案として示す。",TreatyAction.Accept=>"この版の条件に承諾する。",TreatyAction.Confirm=>"承諾書が届き、この版の成立を確認した。",TreatyAction.Decline=>"この条件には承諾できない。",_=>"この独立条項と期間で条約を結びたい。"};PresentWork("正式条約の書状",line,"第"+p.Terms.Version+"版 ／ "+TreatyClauses(p.Terms.Clauses)+" ／ 解除予告 "+p.Terms.NoticeSeconds/86400+"日前 ／ 元期限 "+p.Terms.Until+"秒",p.Author,p.Author,"条約の差出人","開封した本文");if(OwnPoliticalHouse(w) is {} own){void Answer(TreatyAction action){Submit(Session.NegotiateTreaty(new(new("request:treaty-answer-ui/"+shown+"/"+action),action,own,p.Input.Owner,p.Input.Id),Session.PlayerControl,shown));CloseBottomTalk();}if(card?.CanAccept==true){Choice("treaty-accept","この版に承諾して返書する",()=>Answer(TreatyAction.Accept));Choice("treaty-decline","この版は辞退する",()=>Answer(TreatyAction.Decline));}if(p.Input.Action==TreatyAction.Accept&&!w.Treaties.Papers.Any(q=>q.Input.Source==p.Input.Id&&q.Author==Session.PlayerControl))Choice("treaty-confirm","承諾の到達と成立を確認して返書する",()=>Answer(TreatyAction.Confirm));}}
        Choice("treaty-map","地図へ戻る",CloseBottomTalk);LayoutBottomTalk();
    }
}
